import numpy as np


def _stable_log_softmax(logits: np.ndarray, axis: int = -1) -> np.ndarray:
    z = np.asarray(logits, dtype=np.float64)
    if not np.all(np.isfinite(z)):
        raise ValueError("logits must be finite")
    maximum = np.max(z, axis=axis, keepdims=True)
    shifted = z - maximum
    return shifted - np.log(np.exp(shifted).sum(axis=axis, keepdims=True))


def exact_kl_from_logits(p_logits: np.ndarray, q_logits: np.ndarray) -> np.ndarray:
    p_logits = np.asarray(p_logits, dtype=np.float64)
    q_logits = np.asarray(q_logits, dtype=np.float64)
    if p_logits.shape != q_logits.shape:
        raise ValueError("p_logits and q_logits must have the same shape")
    log_p = _stable_log_softmax(p_logits, axis=-1)
    log_q = _stable_log_softmax(q_logits, axis=-1)
    p = np.exp(log_p)
    return np.sum(p * (log_p - log_q), axis=-1)


def kl_sample_values(log_q: np.ndarray, log_p: np.ndarray) -> dict[str, np.ndarray]:
    log_q = np.asarray(log_q, dtype=np.float64)
    log_p = np.asarray(log_p, dtype=np.float64)
    if log_q.shape != log_p.shape or not (np.all(np.isfinite(log_q)) and np.all(np.isfinite(log_p))):
        raise ValueError("log_q and log_p must be finite arrays of the same shape")
    log_ratio = log_p - log_q
    ratio = np.exp(log_ratio)
    return {
        "k1": -log_ratio,
        "k2": 0.5 * log_ratio**2,
        "k3": ratio - 1.0 - log_ratio,
    }
```

Неотрицательность k3 следует из неравенства $u-1-\log u\ge 0$ для $u>0$; небольшой отрицательный результат порядка машинной точности допустимо отсечь только при отображении, но не следует скрывать крупную численную ошибку.

