import numpy as np


def _softmax_1d(logits: np.ndarray, temperature: float = 1.0) -> np.ndarray:
    z = np.asarray(logits, dtype=np.float64)
    if z.ndim != 1 or z.size == 0 or not np.all(np.isfinite(z)):
        raise ValueError("logits must be a non-empty finite one-dimensional array")
    if not np.isfinite(temperature) or temperature <= 0.0:
        raise ValueError("temperature must be a positive finite number")
    scaled = z / temperature
    shifted = scaled - np.max(scaled)
    probabilities = np.exp(shifted)
    return probabilities / probabilities.sum()


def _renormalize_support(probabilities: np.ndarray, keep: np.ndarray) -> np.ndarray:
    out = np.zeros_like(probabilities, dtype=np.float64)
    out[keep] = probabilities[keep]
    mass = float(out.sum())
    if mass <= 0.0:
        raise ValueError("the retained support has zero probability mass")
    return out / mass


def temperature_distribution(logits: np.ndarray, temperature: float) -> np.ndarray:
    return _softmax_1d(logits, temperature)


def top_k_distribution(logits: np.ndarray, k: int) -> np.ndarray:
    probabilities = _softmax_1d(logits)
    if isinstance(k, bool) or not isinstance(k, (int, np.integer)) or not (1 <= int(k) <= probabilities.size):
        raise ValueError("k must be an integer between 1 and the vocabulary size")
    order = np.argsort(-probabilities, kind="stable")
    return _renormalize_support(probabilities, order[: int(k)])


def top_p_distribution(
    logits: np.ndarray,
    top_p: float,
    *,
    min_tokens_to_keep: int = 1,
) -> np.ndarray:
    probabilities = _softmax_1d(logits)
    if not np.isfinite(top_p) or not (0.0 < top_p <= 1.0):
        raise ValueError("top_p must lie in (0, 1]")
    if (
        isinstance(min_tokens_to_keep, bool)
        or not isinstance(min_tokens_to_keep, (int, np.integer))
        or not (1 <= int(min_tokens_to_keep) <= probabilities.size)
    ):
        raise ValueError("min_tokens_to_keep must be a valid positive integer")

    order = np.argsort(-probabilities, kind="stable")
    cumulative = np.cumsum(probabilities[order])
    threshold_count = int(np.searchsorted(cumulative, top_p, side="left")) + 1
    keep_count = max(int(min_tokens_to_keep), threshold_count)
    return _renormalize_support(probabilities, order[:keep_count])
```

Если затем нужен логарифм усечённого распределения, нулевым вероятностям следует сопоставить $-\infty$ явно. Эти три функции проверяют отдельные операции; в полном декодере их можно последовательно компоновать в документированном порядке.
